INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 23, 'theory', 'Quiz: generators');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 0, 'What happens when you call the generator function def g(): yield 1; print(''x'')?', '["x gets printed", "A generator object is returned, the body does not run yet", "The number 1 is returned", "An error"]', 1, 'A call only creates the generator: the code runs in portions on requests from next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 1, 'g = (x * x for x in range(3)); list(g); list(g). What will the second list return?', '["[0, 1, 4]", "[]", "An error", "None"]', 1, 'A generator expression is single-use: after the first pass the generator is exhausted.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 2, 'How does yield differ from return?', '["It does not", "yield gives a value and pauses the function, keeping its state", "yield ends the program", "return works only in generators"]', 1, 'After a yield, execution continues from the same place on the next next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 3, 'What does yield from flat(x) do?', '["Returns a list from flat(x)", "Hands out, one by one, all values of the nested generator", "Ends the generator", "Copies x"]', 1, 'yield from delegates the work to another iterator and spares you a manual loop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 23, 4, 'When is a generator expression better than a list comprehension?', '["When you need access by index", "When the result is folded once, such as sum(...), without keeping everything in memory", "When there is little data", "Never"]', 1, 'A lazy expression creates no list: the values are born one at a time and counted at once.');
